DROP TABLE IF EXISTS `tblRACES`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tblRACES` (
  `Race_Number` mediumint(9) NOT NULL default '0',
  `Race_Name` varchar(75) NOT NULL default '',
  `Race_Date` datetime NOT NULL default '0000-00-00 00:00:00',
  `Points` float NOT NULL default '0',
  `Team_Points` float NOT NULL default '0',
  `Distance` varchar(50) NOT NULL default '',
  `Location` varchar(50) NOT NULL default '',
  `Race_abbreviation` varchar(15) NOT NULL default '',
  `Race_FileName` varchar(50) NOT NULL default '',
  `Series` varchar(5) NOT NULL default '',
  `WebSite` varchar(100) NOT NULL default '',
  `StandardMoney` enum('N','Y') NOT NULL default 'N',
  `IndividualMoney` float NOT NULL default '0',
  `TeamMoney` float NOT NULL default '0',
  `IndividualBreakdown` varchar(250) NOT NULL default '',
  `TeamBreakdown` varchar(250) NOT NULL default '',
  `DoubleDipping` enum('N','Y') NOT NULL default 'N',
  `age30` enum('N','Y') NOT NULL default 'Y',
  `age35` enum('N','Y') NOT NULL default 'Y',
  `age40` enum('N','Y') NOT NULL default 'Y',
  `age45` enum('N','Y') NOT NULL default 'Y',
  `age50` enum('N','Y') NOT NULL default 'Y',
  `age55` enum('N','Y') NOT NULL default 'Y',
  `age60` enum('N','Y') NOT NULL default 'Y',
  `age65` enum('N','Y') NOT NULL default 'Y',
  `age70` enum('N','Y') NOT NULL default 'Y',
  `age75` enum('N','Y') NOT NULL default 'Y',
  `FinalMoney` enum('N','Y') NOT NULL default 'N',
  UNIQUE KEY `Race_Number` (`Race_Number`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

