--
-- Table structure for table `score_sheet`
--

DROP TABLE IF EXISTS `score_sheet`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `score_sheet` (
  `score_sheet_id` int(6) unsigned NOT NULL auto_increment,
  `race_number` int(6) unsigned NOT NULL default '0',
  `submitter` varchar(150) NOT NULL default '',
  `submitter_ip` varchar(50) NOT NULL default '',
  `when_submitted` datetime NOT NULL default '0000-00-00 00:00:00',
  `cc_emails` varchar(255) NOT NULL default '',
  `club_no` int(5) unsigned NOT NULL default '0',
  `division` enum('M-Open','F-Open','M-40','F-40','M-50','F-50','M-60','F-60','M-70','F-70') NOT NULL default 'M-Open',
  `team_type` enum('A','B') NOT NULL default 'A',
  `runners` mediumtext NOT NULL,
  `comments` mediumtext NOT NULL,
